import { Client, Wallet, xrpToDrops } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const iss = Wallet.fromSeed('<TESTNET_SEED_REDACTED>')
async function sub(tx, w) {
  try {
    const r = await c.submitAndWait(tx, { wallet: w, autofill: true })
    return r.result.meta.TransactionResult + (r.result.meta.mpt_issuance_id ? ' ' + r.result.meta.mpt_issuance_id : '')
  } catch (e) { return 'ERR ' + e.message }
}
const log = (k, v) => console.log(k.padEnd(50), v)
let r = await sub({ TransactionType: 'MPTokenIssuanceCreate', Account: iss.address, Flags: 2 | 4 | 32 | 64, AssetScale: 0 }, iss)
log('create', r); const id = r.split(' ')[1]
const h1 = Wallet.generate(), h2 = Wallet.generate()
for (const h of [h1, h2]) log('fund', await sub({ TransactionType: 'Payment', Account: iss.address, Destination: h.address, Amount: xrpToDrops(3) }, iss))
for (const h of [h1, h2]) log('optin', await sub({ TransactionType: 'MPTokenAuthorize', Account: h.address, MPTokenIssuanceID: id }, h))
const pay = (from, to, v) => sub({ TransactionType: 'Payment', Account: from.address, Destination: to.address, Amount: { mpt_issuance_id: id, value: String(v) } }, from)
const set = (flags, holder) => sub({ TransactionType: 'MPTokenIssuanceSet', Account: iss.address, MPTokenIssuanceID: id, Flags: flags, ...(holder ? { Holder: holder.address } : {}) }, iss)
const auth = (h, flags = 0) => sub({ TransactionType: 'MPTokenAuthorize', Account: iss.address, MPTokenIssuanceID: id, Holder: h.address, Flags: flags }, iss)
const claw = (h, v) => sub({ TransactionType: 'Clawback', Account: iss.address, Holder: h.address, Amount: { mpt_issuance_id: id, value: String(v) } }, iss)
const bal = async (h) => { try { const e = await c.request({ command: 'ledger_entry', mptoken: { mpt_issuance_id: id, account: h.address } }); return JSON.stringify({ amt: e.result.node.MPTAmount, flags: e.result.node.Flags }) } catch (e) { return 'none' } }
log('issuer->h1 unauthorized', await pay(iss, h1, 5))
log('auth h1', await auth(h1)); log('auth h1 again', await auth(h1)); log('auth h2', await auth(h2))
log('issuer->h1 100', await pay(iss, h1, 100)); log('issuer->h2 100', await pay(iss, h2, 100))
log('lock h1', await set(1, h1)); log('lock h1 again', await set(1, h1))
log('h1(locked)->issuer 1', await pay(h1, iss, 1))
log('issuer->h1(locked) 1', await pay(iss, h1, 1))
log('h2->h1(locked) 1', await pay(h2, h1, 1))
log('h1(locked)->h2 1', await pay(h1, h2, 1))
log('claw h1(locked) 1', await claw(h1, 1))
log('unlock h1', await set(2, h1)); log('unlock h1 again', await set(2, h1))
log('global lock', await set(1)); log('global lock again', await set(1))
log('issuer->h1 (global) 1', await pay(iss, h1, 1))
log('h1->issuer (global) 1', await pay(h1, iss, 1))
log('h1->h2 (global) 1', await pay(h1, h2, 1))
log('claw h1 (global) 1', await claw(h1, 1))
log('global unlock', await set(2))
log('unauth h1 with balance', await auth(h1, 1)); log('h1 state', await bal(h1))
log('unauth h1 again', await auth(h1, 1))
log('h2->h1(unauth) 1', await pay(h2, h1, 1))
log('h1(unauth)->h2 1', await pay(h1, h2, 1))
log('h1(unauth)->issuer 1', await pay(h1, iss, 1))
log('claw h1(unauth) 1', await claw(h1, 1))
log('claw h1 1000000 (> bal)', await claw(h1, 1000000)); log('h1 state', await bal(h1))
log('claw h1 at zero', await claw(h1, 1))
log('h1 delete mptoken', await sub({ TransactionType: 'MPTokenAuthorize', Account: h1.address, MPTokenIssuanceID: id, Flags: 1 }, h1)); log('h1 state', await bal(h1))
log('h1 recreate', await sub({ TransactionType: 'MPTokenAuthorize', Account: h1.address, MPTokenIssuanceID: id }, h1)); log('h1 state', await bal(h1))
log('h2->h1(recreated) 1', await pay(h2, h1, 1))
const iss_e = await c.request({ command: 'ledger_entry', mpt_issuance: id }); console.log(JSON.stringify(iss_e.result.node))
// cleanup h2 and issuance
log('claw h2 all', await claw(h2, 1000000))
for (const h of [h1, h2]) log('h delete', await sub({ TransactionType: 'MPTokenAuthorize', Account: h.address, MPTokenIssuanceID: id, Flags: 1 }, h))
log('destroy', await sub({ TransactionType: 'MPTokenIssuanceDestroy', Account: iss.address, MPTokenIssuanceID: id }, iss))
for (const h of [h1, h2]) log('accountdelete', await sub({ TransactionType: 'AccountDelete', Account: h.address, Destination: iss.address }, h))
await c.disconnect()

