  it('accepts the flags we create issuances with', () => {
    assert.deepEqual(issuanceProblems(compliant, ISSUER), [])
    assert.deepEqual(issuanceProblems({ Issuer: ISSUER, Flags: creationFlags(false) }, ISSUER), [])
