import { readFileSync } from 'node:fs'
import { Client, Wallet } from 'xrpl'
import { TransactionSubmitter } from './src/index.js'

const ID = '014278CF65068CD39D58A4C8DBC03E0BB731B9AC967D3124'
const keys = JSON.parse(readFileSync('holders.1790652669755.local.json', 'utf8')) as Record<string, { seed: string }>
const client = new Client('wss://s.altnet.rippletest.net:51233')
await client.connect()
const issuer = Wallet.fromSeed(process.env.ISSUER_SEED ?? '')
const is = new TransactionSubmitter(client, issuer, console)
for (const [name, k] of Object.entries(keys)) {
  const w = Wallet.fromSeed(k.seed)
  try {
    const e = await client.request({ command: 'ledger_entry', mptoken: { mpt_issuance_id: ID, account: w.classicAddress }, ledger_index: 'validated' })
    const amt = (e.result.node as { MPTAmount?: string }).MPTAmount
    if (amt !== undefined) {
      await is.submit({ TransactionType: 'Clawback', Account: issuer.classicAddress, Holder: w.classicAddress, Amount: { mpt_issuance_id: ID, value: amt } })
      console.log(name, 'clawed back', amt)
    }
  } catch (err) { console.log(name, 'no mptoken?', String(err)) }
  await new TransactionSubmitter(client, w, console).submit({ TransactionType: 'MPTokenAuthorize', Account: w.classicAddress, MPTokenIssuanceID: ID, Flags: 1 })
  console.log(name, 'mptoken deleted')
}
await is.submit({ TransactionType: 'MPTokenIssuanceDestroy', Account: issuer.classicAddress, MPTokenIssuanceID: ID })
console.log('issuance destroyed')
const ao = await client.request({ command: 'account_objects', account: issuer.classicAddress, ledger_index: 'validated' })
console.log('issuer objects remaining:', ao.result.account_objects.length)
await client.disconnect()

