import { readFileSync } from 'node:fs'
import { Client } from 'xrpl'
const r = JSON.parse(readFileSync('result.json', 'utf8'))
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const iss = (await c.request({ command: 'ledger_entry', mpt_issuance: r.issuanceId, ledger_index: 'validated' })).result.node
console.log('issuance', { Issuer: iss.Issuer, Flags: iss.Flags, flagsHex: iss.Flags.toString(16), Outstanding: iss.OutstandingAmount, AssetScale: iss.AssetScale, DomainID: iss.DomainID })
for (const [k, a] of Object.entries(r.holders)) {
  const n = (await c.request({ command: 'ledger_entry', mptoken: { mpt_issuance_id: r.issuanceId, account: a }, ledger_index: 'validated' })).result.node
  console.log(k, a, { MPTAmount: n.MPTAmount ?? '0', locked: !!(n.Flags & 1), authorized: !!(n.Flags & 2) })
}
const ao = await c.request({ command: 'account_objects', account: iss.Issuer, ledger_index: 'validated' })
console.log('issuer objects:', ao.result.account_objects.map((o) => o.LedgerEntryType))
await c.disconnect()

